void AAssetSpawner_C::ValidDecorPath(const class FString& Path, bool* Valid)
{
	static class UFunction* Func = nullptr;

	if (Func == nullptr)
		Func = Class->GetFunction("AssetSpawner_C", "ValidDecorPath");

	Params::AssetSpawner_C_ValidDecorPath Parms{};

	Parms.Path = std::move(Path);

	UObject::ProcessEvent(Func, &Parms);

	if (Valid != nullptr)
		*Valid = Parms.Valid;
}

